from __future__ import annotations

import os
from html import escape

from app.platform.auth.service import build_auth_summary
from app.platform.company_intelligence.service import build_company_intelligence_summary
from app.platform.founder_console.service import build_founder_console_summary


def render_board_room_experience() -> str:
    auth = build_auth_summary()
    intelligence = build_company_intelligence_summary()
    console = build_founder_console_summary()
    founder_email = escape(os.getenv("FOUNDER_EMAIL", "founder@ai-software-factory.local"))
    ai_status = escape(f"{console['runtime']['ai_provider']} · {console['runtime']['model']}")
    completion = escape(str(intelligence.get("completion_percent", 0)))
    return f"""
<!doctype html><html><head><meta charset='utf-8'/><meta name='viewport' content='width=device-width,initial-scale=1'/><title>Board Room</title>
<style>
:root{{font-family:Inter,system-ui,sans-serif;color-scheme:dark;--bg:#050b14;--panel:#0d1728;--line:#24324a;--text:#f4f8ff;--muted:#9aa8bd;--blue:#3b82f6;--purple:#8b5cf6;--green:#22c55e;--amber:#f59e0b}}*{{box-sizing:border-box}}body{{margin:0;background:radial-gradient(circle at top left,#12305f,#050b14 45%,#020617);color:var(--text)}}button,input,textarea{{font:inherit}}button{{cursor:pointer}}.muted,.small{{color:var(--muted)}}.small{{font-size:12px}}.login{{min-height:100vh;display:grid;place-items:center;padding:28px}}.login-card,.card{{border:1px solid var(--line);background:linear-gradient(180deg,rgba(17,31,52,.94),rgba(7,13,25,.9));border-radius:18px;padding:18px;box-shadow:0 24px 80px rgba(0,0,0,.18)}}.login-card{{width:min(480px,100%);padding:30px}}label{{display:block;margin:14px 0 6px;color:var(--muted);font-size:13px}}input,textarea{{width:100%;border:1px solid var(--line);background:#07101e;color:var(--text);border-radius:12px;padding:13px;outline:0}}.primary,.login-card button{{border:0;border-radius:12px;padding:12px 16px;background:linear-gradient(135deg,var(--blue),var(--purple));color:white;font-weight:800}}.secondary,.logout{{border:1px solid var(--line);border-radius:12px;padding:10px 13px;background:#132238;color:#dbeafe;font-weight:800}}.login-card button{{width:100%;margin-top:14px}}.error{{color:#ff9b9b;margin-top:12px;min-height:22px}}.app{{display:none;grid-template-columns:270px 1fr;min-height:100vh}}aside{{height:100vh;position:sticky;top:0;overflow:auto;padding:20px 16px;background:rgba(4,10,20,.9);border-right:1px solid var(--line)}}main{{padding:22px;min-width:0}}.logo{{font-weight:900;font-size:20px;margin-bottom:18px}}.logo span{{display:block;color:#93c5fd;font-size:12px;letter-spacing:.1em;text-transform:uppercase}}.nav button{{width:100%;text-align:left;margin:4px 0}}.topbar{{display:flex;justify-content:space-between;gap:14px;align-items:center;margin-bottom:16px}}.top-actions{{display:flex;gap:10px;align-items:center;flex-wrap:wrap}}.pill{{display:inline-flex;gap:8px;border:1px solid var(--line);background:#101a2c;border-radius:999px;padding:7px 11px;font-size:13px}}.dot{{width:8px;height:8px;border-radius:50%;background:var(--green);display:inline-block;margin-top:5px}}.layout{{display:grid;grid-template-columns:minmax(0,1fr) 380px;gap:14px}}.meeting{{height:calc(100vh - 110px);display:grid;grid-template-rows:auto 1fr auto;gap:12px}}.thread{{overflow:auto;border:1px solid var(--line);background:#060d18;border-radius:16px;padding:16px}}.msg{{display:grid;grid-template-columns:44px 1fr;gap:12px;margin-bottom:15px}}.avatar{{width:42px;height:42px;border-radius:14px;display:grid;place-items:center;font-weight:900;background:#132238}}.founder{{background:linear-gradient(135deg,#f59e0b,#fef3c7);color:#111827}}.board{{background:linear-gradient(135deg,#2563eb,#8b5cf6)}}.corpsec{{background:linear-gradient(135deg,#0f766e,#22c55e)}}.bubble{{border:1px solid var(--line);background:#0b1424;border-radius:16px;padding:13px;line-height:1.45;white-space:pre-wrap}}.speaker{{display:flex;justify-content:space-between;margin-bottom:6px}}.composer{{display:grid;grid-template-columns:1fr auto;gap:10px}}.composer textarea{{min-height:86px;resize:vertical}}.chips{{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}}.chip{{border:1px solid var(--line);background:#111d31;border-radius:999px;padding:8px 12px;font-size:13px;color:#dbeafe;cursor:pointer}}.minutes{{height:calc(100vh - 110px);display:grid;grid-template-rows:auto 1fr auto;gap:12px}}.minutes-body{{overflow:auto;display:grid;gap:12px}}.minute{{border:1px solid var(--line);background:#08111f;border-radius:14px;padding:13px}}.minute h3{{font-size:14px;margin:0 0 8px;color:#d8b4fe;text-transform:uppercase}}.minute ul{{margin:0;padding-left:18px}}pre{{white-space:pre-wrap;margin:0}}@media(max-width:1100px){{.app,.layout{{grid-template-columns:1fr}}aside{{position:relative;height:auto}}.meeting,.minutes{{height:auto}}.thread,.minutes-body{{max-height:60vh}}}}
</style></head><body>
<section id='loginScreen' class='login'><div class='login-card'><div class='small'>AI SOFTWARE FACTORY</div><h1>Board Room Login</h1><p class='muted'>Sign in to enter the conversational Board Room.</p><label>Founder email</label><input id='email' value='{founder_email}'/><label>Password</label><input id='password' type='password' placeholder='FOUNDER_PASSWORD'/><button id='loginBtn'>Enter Board Room</button><div id='loginError' class='error'></div><p class='muted'>Auth: {escape(str(auth.get('status','unknown')))}</p></div></section>
<section id='app' class='app'><aside><div class='logo'>AI Software Factory<span>Board Room</span></div><nav class='nav'><button class='secondary' onclick='seedAudit()'>Start Audit Meeting</button><button class='secondary' onclick='focusComposer("Summarize the decisions, risks, action items, and approvals from this meeting.")'>Summarize Minutes</button><button class='secondary' onclick='newMeeting()'>New Meeting</button><a href='/mission-control/company-intelligence/snapshot' target='_blank'><button class='secondary'>Company Intelligence</button></a></nav><div class='card' style='margin-top:16px'><h3>INT-01 Active</h3><p class='muted'>Board Room receives Company Intelligence before responding.</p><p><span class='pill'><span class='dot'></span>{ai_status}</span></p></div><p><button class='logout' onclick='logout()'>Logout</button></p></aside>
<main><div class='topbar'><div><div class='small'>PRODUCTION · ASIA-SOUTHEAST1</div><h1>Board Room Meeting</h1></div><div class='top-actions'><span class='pill'><span class='dot'></span>Company Intelligence</span><span class='pill'>Autonomy {completion}%</span><button class='logout' onclick='logout()'>Logout</button></div></div><div class='layout'><section class='card meeting'><div><h2>Discussion</h2><p class='muted small'>Multi-turn meeting. Continue typing follow-ups after each response.</p></div><div id='thread' class='thread'></div><div><div class='composer'><textarea id='message' placeholder='Type your next message to the Board Room...'></textarea><button id='sendBtn' class='primary' onclick='sendMessage()'>Send</button></div><div class='chips'><span class='chip' onclick='focusComposer("Yes, approved. Produce the formal Founder Audit Report. Keep it audit-only and do not implement anything yet.")'>Approve Audit Report</span><span class='chip' onclick='focusComposer("Clarify the risks and missing integrations before I approve.")'>Ask risks</span><span class='chip' onclick='approveCurrentMeeting()'>Create Proposal From Minutes</span></div></div></section><section class='card minutes'><div><h2>Corporate Secretary Minutes</h2><p class='muted small'>Decisions, risks, action items, and approvals are recorded here.</p></div><div class='minutes-body'><div class='minute'><h3>Decisions</h3><ul id='decisions'><li>No decision yet.</li></ul></div><div class='minute'><h3>Action Items</h3><ul id='actions'><li>Start discussion.</li></ul></div><div class='minute'><h3>Risks</h3><ul id='risks'><li>Execution requires founder approval.</li></ul></div><div class='minute'><h3>Approval Queue</h3><p id='approvalText' class='muted'>No approval detected yet.</p><button id='approveBtn' class='primary' onclick='approveCurrentMeeting()' disabled>Approve Current Meeting</button></div><div class='minute'><h3>Meeting Record</h3><pre id='meetingRecord'>Waiting...</pre></div></div><button class='secondary' onclick='copyMinutes()'>Copy Minutes</button></section></div></main></section>
<script src='/mission-control/board-room-js'></script>
</body></html>
"""
